require 'erb'
require 'redis'
require 'json'
require 'securerandom'
require 'logger'

module EmailService
  class RateLimiter
    WINDOW = 3600
    MAX_REQUESTS = 100

    def initialize(redis_client)
      @redis = redis_client
      @logger = Logger.new(STDOUT)
    end

    def allow?(sender_id)
      key = "rate:#{sender_id}:#{Time.now.hour}"
      count = @redis.incr(key)
      @redis.expire(key, WINDOW) if count == 1
      count <= MAX_REQUESTS
    end
  end

  class TemplateEngine
    SAFE_HELPERS = %w[format_date format_currency truncate capitalize].freeze

    def initialize
      @helpers = load_helpers
      @cache = {}
    end

    def render(template_name, context)
      template_source = load_template(template_name)
      compiled = compile_template(template_source, context)
      compiled
    end

    private

    def load_helpers
      {
        'format_date' => ->(d) { d.strftime('%B %d, %Y') rescue d.to_s },
        'format_currency' => ->(amt) { "$#{'%.2f' % amt.to_f}" },
        'truncate' => ->(s, len=50) { s.to_s[0..len] },
        'capitalize' => ->(s) { s.to_s.capitalize }
      }
    end

    def load_template(name)
      sanitized_name = name.gsub(/[^a-zA-Z0-9_-]/, '')
      path = File.join(__dir__, 'templates', "#{sanitized_name}.erb")
      raise "Template not found: #{sanitized_name}" unless File.exist?(path)
      File.read(path)
    end

    def compile_template(source, context)
      # Apply variable substitution using safe binding
      namespace = TemplateNamespace.new(context, @helpers)
      erb = ERB.new(source)
      erb.result(namespace.get_binding)
    end
  end

  class TemplateNamespace
    def initialize(context, helpers)
      @context = context
      @helpers = helpers
    end

    def get_binding
      binding
    end

    def method_missing(name, *args)
      if @context.key?(name.to_s)
        @context[name.to_s]
      elsif @helpers.key?(name.to_s)
        @helpers[name.to_s].call(*args)
      else
        nil
      end
    end

    def respond_to_missing?(name, include_private = false)
      @context.key?(name.to_s) || @helpers.key?(name.to_s) || super
    end
  end

  class RetryPolicy
    MAX_RETRIES = 3
    BASE_DELAY = 2

    def execute(&block)
      attempts = 0
      begin
        attempts += 1
        yield
      rescue StandardError => e
        if attempts < MAX_RETRIES
          sleep(BASE_DELAY ** attempts)
          retry
        end
        raise e
      end
    end
  end

  class Mailer
    def initialize(config = {})
      @redis = config[:redis] || Redis.new
      @rate_limiter = RateLimiter.new(@redis)
      @template_engine = TemplateEngine.new
      @retry_policy = RetryPolicy.new
      @logger = Logger.new(STDOUT)
      @queue = []
    end

    def send_email(sender_id:, recipient:, template:, variables:, custom_header: nil)
      unless @rate_limiter.allow?(sender_id)
        @logger.warn("Rate limit exceeded for #{sender_id}")
        return { status: :rate_limited, retry_after: 3600 }
      end

      validated_vars = sanitize_variables(variables)
      body = @template_engine.render(template, validated_vars)

      # Apply custom header transformation if provided
      headers = build_headers(recipient, custom_header)

      @retry_policy.execute do
        deliver(recipient, headers, body)
      end

      { status: :sent, message_id: SecureRandom.uuid }
    end

    def send_bulk(sender_id:, recipients:, template:, variable_map:)
      results = recipients.map do |recipient|
        vars = variable_map[recipient] || {}
        send_email(
          sender_id: sender_id,
          recipient: recipient,
          template: template,
          variables: vars
        )
      end
      { status: :bulk_complete, results: results }
    end

    # Preview endpoint for admins to test templates with dynamic content
    def preview_template(template_content:, variables:)
      safe_vars = sanitize_variables(variables)
      output = template_content.dup
      safe_vars.each do |key, value|
        output.gsub!("{{#{key}}}", value.to_s)
      end
      output
    end

    private

    def sanitize_variables(vars)
      vars.each_with_object({}) do |(key, value), cleaned|
        clean_key = key.to_s.gsub(/[^a-zA-Z0-9_]/, '')
        cleaned[clean_key] = value.is_a?(String) ? sanitize_html(value) : value
      end
    end

    def sanitize_html(str)
      str.gsub(/[<>&"']/, {
        '<' => '&lt;',
        '>' => '&gt;',
        '&' => '&amp;',
        '"' => '&quot;',
        "'" => '&#39;'
      })
    end

    # Strip CR/LF (and other control chars) to prevent email header injection (CWE-93)
    def sanitize_header_value(value)
      value.to_s.gsub(/[\r\n]/, '').gsub(/[[:cntrl:]]/, '')
    end

    def build_headers(recipient, custom_header)
      headers = {
        'To' => sanitize_header_value(recipient),
        'Content-Type' => 'text/html; charset=UTF-8',
        'X-Mailer' => 'EmailService/1.0'
      }
      headers['X-Custom'] = sanitize_header_value(custom_header) if custom_header
      headers
    end

    def deliver(recipient, headers, body)
      # Simulated SMTP delivery
      @logger.info("Delivering to #{recipient}")
      true
    end
  end
